const { filter, sorts, limit, offset } = $.input;

const body = {
  filter: filter || {},
  limit: Math.max(1, Math.min(500, limit || 50)),
  offset: offset || 0
};

if (sorts && Array.isArray(sorts) && sorts.length > 0) {
  body.sorts = sorts;
}

return body;

const resp = $.steps.queryRecords.response || {};
const records = resp.data || [];

const formatted = records.map(r => {
  const id = r.id || {};
  const result = {
    recordId: id.record_id || '',
    webUrl: r.web_url || '',
    createdAt: r.created_at || ''
  };

  // Extract common readable values
  const vals = r.values || {};
  for (const [key, arr] of Object.entries(vals)) {
    if (!Array.isArray(arr) || arr.length === 0) continue;
    const v = arr[0];
    if (v.full_name) result[key] = v.full_name;
    else if (v.email_address) result[key] = v.email_address;
    else if (v.domain) result[key] = v.domain;
    else if (v.value !== undefined) result[key] = v.value;
    else if (v.first_name || v.last_name) result[key] = [v.first_name, v.last_name].filter(Boolean).join(' ');
  }

  return result;
});

return {
  records: formatted,
  totalReturned: formatted.length,
  object: $.input.object,
  summary: `Found ${formatted.length} ${$.input.object} record${formatted.length === 1 ? '' : 's'}`
};
